window.ENGLISH_CARDS = [{"kind":"phrase","front":"straightforward","meaning":"简单明了；不复杂","example":"The route looks pretty straightforward on the map."},{"kind":"phrase","front":"tricky / tricky in places","meaning":"棘手；有些路段难走","example":"The descent is tricky in places."},{"kind":"phrase","front":"rough / rough terrain","meaning":"崎岖的；难走的地形","example":"The terrain gets rough further up."},{"kind":"phrase","front":"steep / get pretty steep","meaning":"陡；变得很陡","example":"The first two kilometres get pretty steep."},{"kind":"phrase","front":"muddy / slippery / rocky / uneven","meaning":"泥泞／湿滑／多石／不平","example":"It was rocky and uneven near the top."},{"kind":"phrase","front":"narrow / exposed","meaning":"狭窄；无遮蔽／临空暴露","example":"The ridge is narrow and exposed."},{"kind":"phrase","front":"further up / down / along","meaning":"再往上／下／前","example":"The path levels out further along."},{"kind":"phrase","front":"a bit of a climb","meaning":"需要爬升一段","example":"It's a bit of a climb at first."},{"kind":"phrase","front":"nothing too crazy / nothing too bad","meaning":"不算太夸张／太糟","example":"It's steep, but nothing too crazy."},{"kind":"phrase","front":"watch your footing / watch your step","meaning":"注意脚下","example":"Watch your footing on those wet rocks."},{"kind":"phrase","front":"push on / keep going","meaning":"继续往前","example":"We decided to push on for another hour."},{"kind":"phrase","front":"keep a steady pace / pick up the pace","meaning":"保持稳定节奏／加快速度","example":"Let's keep a steady pace and see how we feel."},{"kind":"phrase","front":"slow going","meaning":"走得慢；进展缓慢","example":"The loose rocks made it slow going."},{"kind":"phrase","front":"have ... to go","meaning":"还剩……","example":"We've still got six kilometres to go."},{"kind":"phrase","front":"turn back / head back","meaning":"掉头／往回走","example":"If the weather gets worse, we'll turn back."},{"kind":"phrase","front":"keep an eye on","meaning":"留意；观察","example":"I'll keep an eye on the forecast."},{"kind":"phrase","front":"roll in","meaning":"云、雾、坏天气涌来","example":"Dark clouds started rolling in."},{"kind":"phrase","front":"pretty confident I can ...","meaning":"相当有信心能……","example":"I'm pretty confident I can finish this hike."},{"kind":"phrase","front":"adjust to the altitude","meaning":"适应海拔","example":"I need time to adjust to the altitude."},{"kind":"phrase","front":"light-headed / dizzy","meaning":"头昏发飘／眩晕","example":"I started feeling light-headed at altitude."},{"kind":"phrase","front":"play it by ear","meaning":"走一步看一步；根据情况调整（不一定完全没计划）","example":"We can decide where to eat later. Let's play it by ear."},{"kind":"phrase","front":"a close call","meaning":"险些出事；差一点就……","example":"I nearly missed the train. That was a close call."},{"kind":"phrase","front":"put a damper on something","meaning":"给心情、兴致、计划泼冷水","example":"The rain put a damper on our weekend plans."},{"kind":"phrase","front":"get carried away","meaning":"一时上头；做过头","example":"I got carried away and spent way too much."},{"kind":"phrase","front":"be on the fence (about)","meaning":"对某事犹豫不决","example":"I'm still on the fence about joining the trip."},{"kind":"phrase","front":"come in handy","meaning":"派上用场","example":"A power bank might come in handy."},{"kind":"phrase","front":"work around something","meaning":"想办法克服限制／变通处理","example":"We can work around your schedule."},{"kind":"phrase","front":"catch someone off guard","meaning":"让人措手不及","example":"His question caught me off guard."},{"kind":"phrase","front":"make the most of","meaning":"尽量充分利用","example":"Let's make the most of the good weather."},{"kind":"phrase","front":"call it a day","meaning":"收工；今天到此为止","example":"We're exhausted. Let's call it a day."},{"kind":"phrase","front":"wing it","meaning":"不做充分准备，临场发挥","example":"I wouldn't wing it for a job interview."},{"kind":"phrase","front":"a rough outline / a rough plan","meaning":"大致框架；粗略计划","example":"I just need a rough plan, not a detailed itinerary."},{"kind":"phrase","front":"a minute-by-minute schedule","meaning":"精确到每分钟的安排","example":"I don't need a minute-by-minute schedule."},{"kind":"phrase","front":"last-minute plans / at the last minute","meaning":"临时安排／最后关头","example":"I'm not a fan of last-minute plans."},{"kind":"phrase","front":"high-stakes","meaning":"事关重大的；风险较高的","example":"I prepare carefully for high-stakes situations."},{"kind":"phrase","front":"know your limits","meaning":"了解自身极限","example":"You have to know your own limits on a hike."},{"kind":"phrase","front":"take someone's word for it","meaning":"因为某人这么说就相信","example":"I wouldn't just take his word for it."},{"kind":"phrase","front":"more nuanced than ...","meaning":"比……更有细微差别","example":"My approach to planning is more nuanced than that."},{"kind":"phrase","front":"micromanage / micromanagement","meaning":"事无巨细地控制","example":"I like planning, but not micromanagement."},{"kind":"phrase","front":"a general plan but flexible details","meaning":"有总体安排，细节灵活","example":"I prefer a general plan with some flexibility."},{"kind":"phrase","front":"a brutal uphill climb","meaning":"一段非常折磨人的上坡","example":"The first two kilometres were a brutal uphill climb."},{"kind":"phrase","front":"the trail levels out","meaning":"山路变平缓","example":"After the steep section, the trail levels out."},{"kind":"phrase","front":"I've come this far, so I might as well ...","meaning":"都已经走到这了，索性……","example":"I've come this far, so I might as well finish."},{"kind":"phrase","front":"I didn't come all this way just to ...","meaning":"大老远来这儿可不是为了……","example":"I didn't come all this way just to turn back."},{"kind":"phrase","front":"worth the effort / worth it","meaning":"值得付出／值得","example":"The climb was exhausting, but it was worth it."},{"kind":"phrase","front":"breathtaking views","meaning":"美得令人屏息的风景","example":"The views from the ridge were breathtaking."},{"kind":"phrase","front":"settle in / settle into a rhythm","meaning":"渐渐适应／进入节奏","example":"It takes me a while to settle into a rhythm."},{"kind":"phrase","front":"go at your own pace","meaning":"按自己的节奏来","example":"I like hiking solo because I can go at my own pace."},{"kind":"phrase","front":"feel drawn to nature","meaning":"自然而然被大自然吸引","example":"Even people who don't hike may feel drawn to nature."},{"kind":"phrase","front":"let my mind wander","meaning":"任思绪自由飘荡","example":"On long walks, I just let my mind wander."},{"kind":"phrase","front":"switch off","meaning":"让脑子暂时从工作和烦恼中抽离","example":"Being outdoors helps me switch off."},{"kind":"phrase","front":"get something off your chest","meaning":"把憋在心里的事说出来","example":"It's nice to get things off your chest."},{"kind":"phrase","front":"bottle things up","meaning":"把情绪压在心里","example":"You don't have to bottle everything up."},{"kind":"phrase","front":"vent (to someone)","meaning":"向某人倾诉、发牢骚","example":"Sometimes I just need to vent to a friend."},{"kind":"phrase","front":"bring people closer","meaning":"让彼此关系更近","example":"Going through a tough experience can bring people closer."},{"kind":"phrase","front":"strike up a conversation","meaning":"主动和陌生人聊起来","example":"I might strike up a conversation with another hiker."},{"kind":"phrase","front":"a low-pressure opener","meaning":"没有压力的开场白","example":"“Beautiful day, isn't it?” is a low-pressure opener."},{"kind":"phrase","front":"keep to myself","meaning":"喜欢自己待着，不太主动社交","example":"I usually keep to myself when I travel."},{"kind":"phrase","front":"drain someone's energy","meaning":"消耗某人精力","example":"Big social events can drain my energy."},{"kind":"phrase","front":"be open to ...","meaning":"对……持开放态度","example":"I enjoy solo hiking, but I'm open to a chat."},{"kind":"sentence","front":"I'm not the kind of person who needs every little detail planned out.","meaning":"","example":""},{"kind":"sentence","front":"I don't really like being invited somewhere at the last minute.","meaning":"","example":""},{"kind":"sentence","front":"Especially if it's something that takes up a lot of time.","meaning":"","example":""},{"kind":"sentence","front":"A hike can take a whole day, or even several days.","meaning":"","example":""},{"kind":"sentence","front":"I'd read up on the trail and check where it's safe to stay overnight.","meaning":"","example":""},{"kind":"sentence","front":"He'd need to know my fitness level and how active I normally am.","meaning":"","example":""},{"kind":"sentence","front":"They can't guarantee it'll be safe for me.","meaning":"","example":""},{"kind":"sentence","front":"The thought of hiking at 4,500 metres put a damper on my excitement.","meaning":"","example":""},{"kind":"sentence","front":"A lot of things can go wrong at high altitude.","meaning":"","example":""},{"kind":"sentence","front":"The first two kilometres are a brutal uphill climb.","meaning":"","example":""},{"kind":"sentence","front":"Every hike I've done has felt worth it in the end.","meaning":"","example":""},{"kind":"sentence","front":"The more trails you hike, the more similar the scenery can start to feel.","meaning":"","example":""},{"kind":"sentence","front":"I've seen just about every kind of landscape.","meaning":"","example":""},{"kind":"sentence","front":"Travel halfway around the world.","meaning":"","example":""},{"kind":"sentence","front":"People spend too much time indoors, especially in offices and cities.","meaning":"","example":""},{"kind":"sentence","front":"I can just let my mind wander without any interruptions.","meaning":"","example":""},{"kind":"sentence","front":"You can complain freely without being judged.","meaning":"","example":""},{"kind":"sentence","front":"You don't have to bottle everything up or deal with those feelings on your own.","meaning":"","example":""},{"kind":"sentence","front":"When you both vent about how exhausting the hike is, it can bring you closer.","meaning":"","example":""},{"kind":"sentence","front":"I'm an introvert, and there usually aren't many people on those trails.","meaning":"","example":""},{"kind":"sentence","front":"I'd go up to them and say hi.","meaning":"","example":""},{"kind":"sentence","front":"Hey, how's it going? Beautiful view, isn't it?","meaning":"","example":""},{"kind":"paragraph","front":"I'm an INTJ, and I definitely prefer having some kind of plan. I don't need a minute-by-minute schedule, but I'm not a big fan of last-minute decisions either, especially when something takes up a whole day or more. If it's just a short, straightforward hike at low altitude, I'm happy to be flexible. But for a multi-day hike or anything at high altitude, I wouldn't just wing it. I'd read up on the route, check the weather, and make sure I know what I'm getting into.","meaning":"","example":""},{"kind":"paragraph","front":"One thing I've noticed is that some hikes are toughest right at the beginning. I remember a trail where the first two kilometres were a brutal uphill climb. Once I'd got through that section, the path levelled out and the rest was much more straightforward. Even when I feel exhausted, I sometimes tell myself, “I've come this far, so I might as well keep going.” Most of the time, the views turn out to be breathtaking, and I feel it was worth the effort. Of course, I'd turn back if conditions got genuinely dangerous.","meaning":"","example":""},{"kind":"paragraph","front":"I love hiking for the scenery, but it's not just about the views. What I really enjoy is the sense of freedom. Sometimes I completely switch off and just take in what's around me. Other times, I let my mind wander. I might think about work, the stock market, or random things that have been bothering me, but I still feel relaxed. Out there, nobody's constantly interrupting me or handing me another task. I can think about whatever I want, at my own pace.","meaning":"","example":""},{"kind":"paragraph","front":"I'm quite introverted, so most of the time I'd rather hike on my own. I like being able to go at my own pace and enjoy the peace and quiet. But that doesn't mean I don't want to talk to anyone. If I run into another hiker, I'm happy to say hi, and sometimes I might strike up a conversation. Something simple like “Beautiful view, isn't it?” is enough. I like having the freedom to chat when I feel like it, without feeling obligated to socialize the whole time.","meaning":"","example":""},{"kind":"sentence","front":"I made 200 this month.","meaning":"","example":""},{"kind":"sentence","front":"I only made 200 this month.","meaning":"","example":""},{"kind":"sentence","front":"Why do I have so much to do?","meaning":"","example":""},{"kind":"sentence","front":"I've got a lot on my plate right now.","meaning":"","example":""},{"kind":"sentence","front":"I've been swamped lately.","meaning":"","example":""},{"kind":"phrase","front":"not worth the risk","meaning":"不值得冒这个风险","example":"I'd rather turn down the offer. It's not worth the risk of losing my student status."},{"kind":"phrase","front":"drizzle / light drizzle","meaning":"毛毛雨","example":"It's only drizzling. We can still walk to the shops."},{"kind":"phrase","front":"light rain / steady rain / heavy rain / pour","meaning":"小雨／持续降雨／大雨／倾盆大雨","example":"If it's pouring outside, I'll just stay in."},{"kind":"phrase","front":"hail / hailstone","meaning":"冰雹／冰雹颗粒","example":"It started hailing out of nowhere."},{"kind":"phrase","front":"light breeze / strong wind / gust / gusty","meaning":"微风／强风／阵风／多阵风的","example":"I love a warm, breezy day, but not when it's really gusty."},{"kind":"phrase","front":"the wind picks up / eases off","meaning":"风越来越大／风减弱","example":"The wind picked up around noon but eased off later."},{"kind":"phrase","front":"the rain eases off","meaning":"雨势渐小","example":"We can head out once the rain eases off."},{"kind":"phrase","front":"clear up","meaning":"天气转晴；澄清（视语境）","example":"It looks like it'll clear up this afternoon."},{"kind":"phrase","front":"cool / chilly / cold / freezing / bitterly cold","meaning":"凉快／冷飕飕／冷／冷得厉害／刺骨的冷","example":"It's chilly this morning, but not freezing."},{"kind":"phrase","front":"visibility / poor visibility","meaning":"能见度／能见度差","example":"The fog was so thick that visibility was terrible."},{"kind":"phrase","front":"have time to myself","meaning":"有属于自己的独处时间","example":"I need a little time to myself after work."},{"kind":"phrase","front":"whenever I want","meaning":"想什么时候就什么时候","example":"On my day off, I like being able to go out whenever I want."},{"kind":"phrase","front":"if I feel like it / don't feel like doing","meaning":"想做就做／不太想做","example":"I'll go out if I feel like it, but I don't feel like making plans yet."},{"kind":"phrase","front":"too much hassle","meaning":"太麻烦；太折腾","example":"Planning another trip right now feels like too much hassle."},{"kind":"phrase","front":"be supposed to","meaning":"本来应该／按安排应该","example":"We were supposed to meet at eight."},{"kind":"phrase","front":"at the last minute","meaning":"临到最后一刻","example":"I don't mind a last-minute change if you tell me right away."},{"kind":"phrase","front":"something came up","meaning":"临时有事；突然出了状况","example":"Sorry, something came up and I can't make it tonight."},{"kind":"phrase","front":"push something back","meaning":"把某项安排往后推","example":"Can we push our meeting back by an hour?"},{"kind":"phrase","front":"wait around","meaning":"干等、白等","example":"I don't want to wait around for two hours without an update."},{"kind":"phrase","front":"end up doing","meaning":"最后／结果做了某事","example":"We ended up going home instead."},{"kind":"phrase","front":"a couple of things are bothering me","meaning":"有几件事让我放心不下","example":"A couple of things about this offer are bothering me."},{"kind":"phrase","front":"raise ethical concerns","meaning":"引发诚信/伦理上的担忧（略正式但常用）","example":"Making up experience on a CV raises ethical concerns."},{"kind":"phrase","front":"make things up","meaning":"编造事实","example":"I don't want to make things up just to land a job."},{"kind":"phrase","front":"exaggerate my experience","meaning":"夸大工作经验","example":"I'd rather be honest than exaggerate my experience."},{"kind":"phrase","front":"a red flag","meaning":"危险信号；令人警觉之处","example":"Being told to keep up a false story is a red flag."},{"kind":"phrase","front":"keep up an image / keep up appearances","meaning":"维持某种形象／做表面功夫","example":"I'd have to keep up an image that isn't really me."},{"kind":"phrase","front":"if it comes out / comes to light","meaning":"如果事情曝光；被发现","example":"If it comes out, it could have serious consequences."},{"kind":"phrase","front":"face consequences","meaning":"承担后果","example":"The agency could face consequences too."},{"kind":"phrase","front":"take time off","meaning":"请假、休假","example":"I need to take time off for exams."},{"kind":"phrase","front":"spread out throughout the semester","meaning":"分散在整个学期","example":"My exams are spread out throughout the semester."},{"kind":"phrase","front":"commit to a full-time role","meaning":"承诺投入全职岗位","example":"I can't commit to a full-time role right now."},{"kind":"phrase","front":"turn down an offer / decline an offer","meaning":"拒绝工作机会（decline 较正式）","example":"I've decided to turn down the offer."},{"kind":"phrase","front":"walk away","meaning":"选择退出，不再继续","example":"Sometimes it's better to walk away."},{"kind":"phrase","front":"stay in touch","meaning":"保持联系","example":"I'd be happy to stay in touch for future opportunities."},{"kind":"phrase","front":"jeopardize something","meaning":"使某事面临风险","example":"I don't want to jeopardize my degree."},{"kind":"phrase","front":"at the end of the day","meaning":"说到底，归根结底","example":"At the end of the day, finishing my degree comes first."},{"kind":"phrase","front":"gross me out","meaning":"让我恶心、反胃","example":"Finding the toilet unflushed really grosses me out."},{"kind":"phrase","front":"run out of patience","meaning":"耐心耗尽","example":"I've run out of patience with this situation."},{"kind":"phrase","front":"flush the toilet / hold down the button","meaning":"冲厕所／按住按钮","example":"Maybe he didn't hold down the flush button long enough."},{"kind":"phrase","front":"give someone the benefit of the doubt","meaning":"暂时往好处想，相信对方不是故意的（建议延伸）","example":"I gave him the benefit of the doubt at first."},{"kind":"phrase","front":"my first sip / take a sip","meaning":"第一口（饮品）／抿一口","example":"The moment I took my first sip, I knew I hated it."},{"kind":"phrase","front":"spit it out / spat it out","meaning":"把东西吐出来／过去式","example":"The coffee tasted awful, so I spat it out."},{"kind":"phrase","front":"put someone off something","meaning":"使某人对某物失去兴趣、产生反感","example":"The smell puts me off coffee."},{"kind":"phrase","front":"the aftertaste","meaning":"余味，回味","example":"I can't stand the bitter aftertaste."},{"kind":"phrase","front":"coffee isn't for me","meaning":"咖啡不适合我；我不喜欢咖啡","example":"Thanks, but coffee just isn't for me."},{"kind":"phrase","front":"gentle and comforting","meaning":"温和、让人舒服安心","example":"Tea feels gentler and more comforting to me."},{"kind":"phrase","front":"oats / oatmeal / peanut butter","meaning":"燕麦／燕麦粥／花生酱","example":"I usually have oats or toast with peanut butter."},{"kind":"phrase","front":"the idea of working full-time puts me off","meaning":"“全职工作这个念头让我反感”","example":"It's not just one company; the idea of working full-time puts me off."},{"kind":"phrase","front":"get enough in return","meaning":"获得足够回报","example":"People work long hours but don't always get enough in return."},{"kind":"phrase","front":"job security is shaky","meaning":"工作稳定性不可靠","example":"Even well-paid jobs can feel insecure when job security is shaky."},{"kind":"phrase","front":"a decent salary / decent pay","meaning":"还不错的工资","example":"A decent salary doesn't necessarily mean a comfortable life."},{"kind":"phrase","front":"be protective of one's time","meaning":"很珍惜、保护自己的时间","example":"Younger workers may be more protective of their free time."},{"kind":"phrase","front":"put food on the table","meaning":"养家糊口；满足基本生存需要","example":"In the past, many people worked simply to put food on the table."},{"kind":"phrase","front":"feel empty / unfulfilled","meaning":"精神空虚／缺乏成就或满足感","example":"You can have enough money and still feel unfulfilled."},{"kind":"phrase","front":"admission fee / admission ticket","meaning":"门票费用／入场票","example":"Some attractions charge a pretty steep admission fee."},{"kind":"phrase","front":"make things worse / intensify","meaning":"加剧、使情况恶化（前者更口语）","example":"Social media can make that pressure worse."},{"kind":"phrase","front":"the goalposts keep moving","meaning":"标准不断抬高，永远不够","example":"Every time people earn more, the goalposts seem to keep moving."},{"kind":"phrase","front":"barrier to entry","meaning":"入门门槛","example":"The cost of equipment is a barrier to entry for skiing."},{"kind":"phrase","front":"have a mind of your own","meaning":"有自己的主见（建议延伸）","example":"You can be influenced by others and still have a mind of your own."},{"kind":"phrase","front":"travel burnout","meaning":"旅行疲劳、旅行倦怠","example":"I think I've got a bit of travel burnout."},{"kind":"phrase","front":"mentally drained / mentally exhausted","meaning":"精神疲惫","example":"After so many trips, I felt mentally drained."},{"kind":"phrase","front":"diminishing returns","meaning":"边际体验递减（生活、商业都能用）","example":"After seeing so many similar churches, there are diminishing returns."},{"kind":"phrase","front":"magnificent / grand","meaning":"宏伟壮观／富丽堂皇","example":"The cathedral was absolutely magnificent."},{"kind":"phrase","front":"intricate stone carvings","meaning":"精巧繁复的石雕","example":"I was amazed by the intricate stone carvings."},{"kind":"phrase","front":"underwhelming","meaning":"没预想中惊艳；让人失望","example":"The next church felt a bit underwhelming."},{"kind":"phrase","front":"raise the bar","meaning":"抬高标准或期待","example":"Seeing Rome's churches really raised the bar for me."},{"kind":"phrase","front":"blur together","meaning":"在记忆里逐渐混成一片","example":"After a while, all those old towns start to blur together."},{"kind":"phrase","front":"stand out","meaning":"格外突出、令人印象深刻","example":"That little chapel actually stood out from the others."},{"kind":"phrase","front":"tick things off a list","meaning":"为打卡而打卡、逐项完成清单","example":"I don't want to spend every trip just ticking things off a list."},{"kind":"phrase","front":"get the most out of something","meaning":"尽量获得最多收获","example":"I used to try to get the most out of every trip."},{"kind":"phrase","front":"feel like work","meaning":"感觉像是在工作／完成任务","example":"Planning a holiday shouldn't feel like work."},{"kind":"phrase","front":"wasn't particularly aware of it at the time","meaning":"当时没有特别清晰地意识到","example":"I wasn't particularly aware of the fatigue at the time."},{"kind":"phrase","front":"much more noticeable now","meaning":"现在更加明显、能清楚感知","example":"That feeling is much more noticeable now."},{"kind":"phrase","front":"at the last minute / last-minute change","meaning":"最后一刻／临时变动","example":"A last-minute change is fine if you tell me right away."},{"kind":"phrase","front":"let someone know right away","meaning":"立即通知某人","example":"Just let me know right away if you can't make it."},{"kind":"phrase","front":"on short notice","meaning":"提前通知时间很短","example":"I don't mind changes on short notice if there's a good reason."},{"kind":"phrase","front":"once in a while / occasionally","meaning":"偶尔","example":"I can understand being late once in a while."},{"kind":"phrase","front":"keep making excuses","meaning":"不断找借口","example":"You can't keep making excuses every time."},{"kind":"phrase","front":"feel disrespected","meaning":"感到不被尊重","example":"If it keeps happening, I start to feel disrespected."},{"kind":"phrase","front":"question the friendship","meaning":"质疑这段友谊是否值得维持","example":"It makes me question the friendship."},{"kind":"phrase","front":"stay friends with someone","meaning":"继续和某人做朋友","example":"I'm not sure I want to stay friends with someone who's always late."},{"kind":"phrase","front":"not worth the hassle","meaning":"不值得这样折腾","example":"Constantly rearranging plans isn't worth the hassle."},{"kind":"sentence","front":"If the forecast says it's going to pour, I'll stay home.","meaning":"","example":""},{"kind":"sentence","front":"I like going hiking on a warm, sunny, breezy day.","meaning":"","example":""},{"kind":"sentence","front":"I'd cancel the plan and stay home.","meaning":"","example":""},{"kind":"sentence","front":"It was an interview for a software testing engineer position.","meaning":"","example":""},{"kind":"sentence","front":"A few things about the offer are bothering me.","meaning":"","example":""},{"kind":"sentence","front":"It raises some serious ethical concerns.","meaning":"","example":""},{"kind":"sentence","front":"There could be serious consequences if it comes to light.","meaning":"","example":""},{"kind":"sentence","front":"It's tempting, but not tempting enough to give up my degree for.","meaning":"","example":""},{"kind":"sentence","front":"It clashes with my exam schedule.","meaning":"","example":""},{"kind":"sentence","front":"I can't commit to a full-time position right now.","meaning":"","example":""},{"kind":"sentence","front":"I'd be happy to stay in touch about future opportunities.","meaning":"","example":""},{"kind":"sentence","front":"I've already decided to turn down the offer.","meaning":"","example":""},{"kind":"sentence","front":"I've run out of patience.","meaning":"","example":""},{"kind":"sentence","front":"I kept giving him the benefit of the doubt.","meaning":"","example":""},{"kind":"sentence","front":"The moment I took my first sip, I spat it out.","meaning":"","example":""},{"kind":"sentence","front":"I had bread with peanut butter.","meaning":"","example":""},{"kind":"sentence","front":"Even the smell of coffee puts me off.","meaning":"","example":""},{"kind":"sentence","front":"Why are so many young people fed up with work?","meaning":"","example":""},{"kind":"sentence","front":"We're far more productive than ever before.","meaning":"","example":""},{"kind":"sentence","front":"Just to put food on the table and avoid going hungry.","meaning":"","example":""},{"kind":"sentence","front":"Feeling empty or unfulfilled.","meaning":"","example":""},{"kind":"sentence","front":"Social media makes that pressure even worse.","meaning":"","example":""},{"kind":"sentence","front":"If you want to go skiing...","meaning":"","example":""},{"kind":"sentence","front":"I just don't have the energy to plan another trip.","meaning":"","example":""},{"kind":"sentence","front":"Other churches might feel underwhelming by comparison.","meaning":"","example":""},{"kind":"sentence","front":"I wasn't particularly aware of that feeling at the time.","meaning":"","example":""},{"kind":"sentence","front":"After a while, they all start to blur together.","meaning":"","example":""},{"kind":"sentence","front":"Sometimes something unexpected comes up at the last minute.","meaning":"","example":""},{"kind":"sentence","front":"I can understand it if it happens once in a while.","meaning":"","example":""},{"kind":"sentence","front":"I'd start wondering whether I even want to stay friends.","meaning":"","example":""},{"kind":"paragraph","front":"I had an interview for a software testing position, and the salary was pretty tempting. But a couple of things bothered me. For one thing, they wanted me to make up experience on my CV and keep up that story once I started working. That's a huge red flag for me. On top of that, the full-time schedule clashes with my exams. At the end of the day, it's just not worth jeopardizing my degree. So I've decided to turn the offer down. I'd rather be upfront about it and stay in touch in case something more suitable comes up later.","meaning":"","example":""},{"kind":"paragraph","front":"Thanks, but coffee really isn't for me. I gave it a try once in Finland, and the moment I took my first sip, I wanted to spit it out. I don't know if it's the bitterness, the smell, or the aftertaste, but the whole thing puts me off. Tea is different, though. Even when it's bitter, I find it gentler and more comforting. So if you've got tea, I'd happily have that instead.","meaning":"","example":""},{"kind":"paragraph","front":"I don't think young people necessarily hate doing anything productive. A lot of us just feel that full-time jobs take up too much of our lives, and we don't always get enough in return. We're more productive than ever, yet the goalposts keep moving. Once you can put food on the table, you start wanting experiences, hobbies, and more freedom. And social media can make that pressure even worse. So there's this contradiction: you need money to enjoy your free time, but you have to give up so much of that time to earn it.","meaning":"","example":""},{"kind":"paragraph","front":"I traveled to a lot of places in a short period, and I think I got a bit burned out. I still love traveling, but planning another trip sometimes feels like work. I've seen so many magnificent churches and intricate stone carvings in Italy that smaller churches can feel a little underwhelming by comparison. It's not that they're bad. It's just that the bar has been raised. After a while, old towns and city halls start to blur together. Looking back, I wasn't particularly aware of how tired I was at the time, but it's much more noticeable now. I'd rather slow down and choose a few places that genuinely interest me.","meaning":"","example":""},{"kind":"phrase","front":"cook most of my meals myself","meaning":"大部分饭自己做","example":"I cook most of my meals myself, whether they’re quick and easy or more time-consuming."},{"kind":"phrase","front":"eat out once or twice a week","meaning":"每周在外面吃一两次","example":"Lately, I’ve been eating out once or twice a week."},{"kind":"phrase","front":"prepare / prep the ingredients","meaning":"准备食材","example":"The actual boiling is quick, but prepping the ingredients takes time."},{"kind":"phrase","front":"add ingredients in the right order","meaning":"按正确顺序下食材","example":"With one pot, I have to add the ingredients in the right order."},{"kind":"phrase","front":"get the timing right","meaning":"掌握烹饪时机","example":"It’s tricky to get the timing right when everything goes into one pot."},{"kind":"phrase","front":"save the quick-cooking ingredients for last","meaning":"易熟食材最后放","example":"I cook the vegetables that take longer first and save the spinach for last."},{"kind":"phrase","front":"turn mushy","meaning":"煮得软烂、糊软","example":"If you add spinach too early, it can turn mushy."},{"kind":"phrase","front":"follow a recipe / improvise","meaning":"按菜谱做／临场发挥","example":"Sometimes I follow a recipe, but often I just improvise."},{"kind":"phrase","front":"time-consuming","meaning":"耗时的","example":"Cooking a full meal can be surprisingly time-consuming."},{"kind":"phrase","front":"a hassle / worth the hassle","meaning":"麻烦事／值得这么折腾","example":"Is it worth the hassle of cooking just to save a little money?"},{"kind":"phrase","front":"a trade-off","meaning":"权衡，有得有失","example":"There’s a trade-off between saving money and saving time."},{"kind":"phrase","front":"pay a little extra for convenience","meaning":"多付一点钱换方便","example":"Sometimes I’m happy to pay a little extra for convenience."},{"kind":"phrase","front":"keep it simple","meaning":"尽量简单处理","example":"On busy days, I keep it simple and boil some eggs and broccoli."},{"kind":"phrase","front":"a shared / communal kitchen","meaning":"公用厨房","example":"I don’t enjoy using the shared kitchen in my dorm."},{"kind":"phrase","front":"unhygienic","meaning":"不卫生的","example":"The communal kitchen often feels unhygienic to me."},{"kind":"phrase","front":"limit my options","meaning":"限制选择","example":"Having only an electric pot really limits my options."},{"kind":"phrase","front":"cookware / kitchenware / kitchen utensils","meaning":"锅具／厨房用品总称／厨用工具","example":"Cleaning my cookware and kitchen utensils afterward takes time."},{"kind":"phrase","front":"stove / stovetop","meaning":"炉灶／炉灶表面","example":"I don’t have a stove or an oven in my dorm room."},{"kind":"phrase","front":"clean up / the cleanup","meaning":"清理（动词）／收拾清洗（名词）","example":"The cleanup sometimes takes longer than the cooking."},{"kind":"phrase","front":"do the math","meaning":"算过账、核算成本","example":"I did the math, and eating out occasionally is affordable for me."},{"kind":"phrase","front":"boil some broccoli","meaning":"煮些西兰花（broccoli 通常不可数）","example":"I can boil some broccoli and eggs in my electric pot."},{"kind":"phrase","front":"a source of protein","meaning":"蛋白质来源","example":"Meat is one source of protein, but it isn’t the only one."},{"kind":"phrase","front":"a cold draft (UK: draught)","meaning":"从窗户透进来的冷风","example":"When I open the window in winter, a cold draft comes in."},{"kind":"phrase","front":"a window seal / a gap in the frame","meaning":"窗户密封条／窗框缝隙","example":"A gap in the window frame can let cold air in."},{"kind":"phrase","front":"noise coming through thin walls","meaning":"穿过薄墙传来的噪音","example":"I can hear noise coming through the thin walls."},{"kind":"phrase","front":"heavy footsteps / chair scrapes","meaning":"沉重脚步声／椅子拖刮声","example":"My neighbor’s heavy footsteps and chair scrapes are distracting."},{"kind":"phrase","front":"a low-frequency thump","meaning":"低频咚咚震动声","example":"The most annoying sound is a low-frequency thump."},{"kind":"phrase","front":"mask the noise","meaning":"用另一种声音掩盖噪音","example":"I want some background noise that can mask the thumping."},{"kind":"phrase","front":"white noise / brown noise","meaning":"白噪音／棕噪音","example":"I’m trying to find background noise that I can tolerate."},{"kind":"phrase","front":"a steady background sound","meaning":"持续稳定的背景声音","example":"A steady background sound can be less distracting than sudden thumps."},{"kind":"phrase","front":"let cold air in","meaning":"让冷空气进入","example":"Opening the window helps with background noise, but it lets cold air in."},{"kind":"phrase","front":"mentally exhausted / mentally drained","meaning":"精神疲惫的／心力交瘁的","example":"After practicing English for an hour, I felt mentally drained."},{"kind":"phrase","front":"make progress / feel frustrated","meaning":"取得进步／感到挫败","example":"I can tell I’m making progress, but I still get frustrated sometimes."},{"kind":"phrase","front":"everyday spoken English","meaning":"日常口语英语","example":"I want to learn the expressions people use in everyday spoken English."},{"kind":"phrase","front":"high-frequency expressions","meaning":"高频表达","example":"I’m focusing on high-frequency expressions rather than rare words."},{"kind":"phrase","front":"follow a lecture","meaning":"听懂、跟上讲座或授课","example":"I couldn’t really follow what the lecturer was saying."},{"kind":"phrase","front":"pay attention in class","meaning":"上课认真听讲","example":"Very few students were actually paying attention in class."},{"kind":"phrase","front":"show up for class","meaning":"出席课程","example":"A lot of students didn’t even show up for class."},{"kind":"phrase","front":"doomscroll / scroll through short videos","meaning":"无止境刷信息流／刷短视频","example":"Some students were just scrolling through short videos on their phones."},{"kind":"phrase","front":"a lab session / lab class","meaning":"实验课","example":"In the lab session, we mainly reviewed mistakes in the materials."},{"kind":"phrase","front":"go over mistakes","meaning":"逐一检查、讲解错误","example":"The lecturer went over the mistakes and explained how to fix them."},{"kind":"phrase","front":"balance studying and working","meaning":"平衡学习和工作","example":"I’m constantly trying to balance studying and working."},{"kind":"phrase","front":"weigh my options","meaning":"权衡各种选项","example":"I have to weigh my options whenever work overlaps with class."},{"kind":"phrase","front":"opportunity cost","meaning":"机会成本：选择一项而放弃的次优收益","example":"If I attend class, the opportunity cost is the money I could have earned."},{"kind":"phrase","front":"give up the chance to earn money","meaning":"放弃挣钱机会","example":"By staying in class, I’m giving up the chance to earn money."},{"kind":"phrase","front":"my time would be better spent elsewhere","meaning":"我的时间花在别处可能更值得","example":"I can’t help but wonder if my time would be better spent elsewhere."},{"kind":"phrase","front":"get something out of something","meaning":"从某事中获得价值／收获","example":"It’s frustrating when I don’t feel I’m getting much out of a class."},{"kind":"phrase","front":"put in the effort / get little in return","meaning":"付出努力／回报很少","example":"I’m willing to put in the effort, but sometimes I get little in return."},{"kind":"phrase","front":"get my point across","meaning":"把意思表达清楚","example":"I can usually get my point across, even if my grammar isn’t perfect."},{"kind":"phrase","front":"have a good command of English","meaning":"很好地掌握英语","example":"I want to have a better command of everyday English."},{"kind":"phrase","front":"master every word","meaning":"掌握每一个词","example":"I don’t need to master every word to communicate effectively."},{"kind":"phrase","front":"major grammatical mistakes","meaning":"严重的语法错误","example":"I want to avoid major grammatical mistakes, but minor ones are fine."},{"kind":"phrase","front":"the flow of a conversation","meaning":"对话的流畅度／节奏","example":"Too much hesitation can interrupt the flow of a conversation."},{"kind":"phrase","front":"speak smoothly and naturally","meaning":"流畅自然地说话","example":"I want to express myself more smoothly and naturally."},{"kind":"phrase","front":"go beyond small talk","meaning":"不止停留在寒暄","example":"I want to go beyond small talk with native speakers."},{"kind":"phrase","front":"have an in-depth conversation","meaning":"进行深入交流","example":"I’d like to have more in-depth conversations about social issues."},{"kind":"phrase","front":"dig a little deeper","meaning":"进一步深入讨论","example":"We can dig a little deeper without turning it into a lecture."},{"kind":"phrase","front":"only scratch the surface","meaning":"仅触及表面","example":"Today we only scratched the surface of the subject."},{"kind":"phrase","front":"take a more academic approach","meaning":"从更偏学术的角度入手","example":"Sometimes I want to take a slightly more academic approach."},{"kind":"phrase","front":"the underlying mechanisms","meaning":"背后的机制","example":"I’m interested in the psychological mechanisms underlying our choices."},{"kind":"phrase","front":"refer to a study / cite an article","meaning":"提及研究／引用论文","example":"In casual conversation, we can refer to a study without formally citing it."},{"kind":"phrase","front":"draw on research","meaning":"借助研究结果支撑观点","example":"You can draw on research without using academic language all the time."},{"kind":"phrase","front":"choose every word with absolute precision","meaning":"字斟句酌、准确选词","example":"I don’t need to choose every word with absolute precision."},{"kind":"phrase","front":"social comparison","meaning":"社会比较","example":"Social comparison existed long before social media."},{"kind":"phrase","front":"in relative rather than absolute terms","meaning":"用相对而非绝对标准衡量","example":"We often judge our success in relative rather than absolute terms."},{"kind":"phrase","front":"the highlight reel of someone’s life","meaning":"他人生活的高光剪辑","example":"Social media mostly shows the highlight reels of other people’s lives."},{"kind":"phrase","front":"hedonic adaptation","meaning":"享乐适应：逐渐习惯生活改善","example":"Hedonic adaptation may help explain why new comforts stop feeling special."},{"kind":"phrase","front":"feel like you’re falling behind","meaning":"觉得自己落后于别人","example":"Seeing other people succeed can make you feel like you’re falling behind."},{"kind":"phrase","front":"act as an amplifier / amplify","meaning":"成为放大器／放大","example":"Social media can act as an amplifier of social comparison."},{"kind":"phrase","front":"set unrealistic expectations","meaning":"制造不切实际的期待","example":"Constant exposure to luxury lifestyles can set unrealistic expectations."},{"kind":"phrase","front":"fuel envy and dissatisfaction","meaning":"加剧羡慕与不满","example":"Unfair comparisons can fuel envy and dissatisfaction."},{"kind":"phrase","front":"measure your self-worth by ...","meaning":"用……衡量自我价值","example":"It’s exhausting to measure your self-worth by other people’s achievements."},{"kind":"phrase","front":"the rat race / be caught up in the rat race","meaning":"激烈的竞争生活／陷入内卷竞争","example":"Some people feel caught up in the rat race from an early age."},{"kind":"phrase","front":"outperform others","meaning":"表现超过别人","example":"Competition becomes stressful when you feel you must always outperform others."},{"kind":"phrase","front":"get ahead","meaning":"出人头地、取得优势","example":"Everyone seems to be trying to get ahead."},{"kind":"phrase","front":"wear someone down","meaning":"使人长期疲惫、消磨意志","example":"Constant comparison can wear people down over time."},{"kind":"phrase","front":"attach too much importance to ...","meaning":"过度看重……","example":"Why do we attach so much importance to being better off than others?"},{"kind":"phrase","front":"compare ourselves with others","meaning":"将自己与他人比较","example":"We’ve been comparing ourselves with others since we were very young."},{"kind":"phrase","front":"exceptional lifestyles as the norm","meaning":"把极少数人的优越生活当作常态","example":"The problem starts when we treat exceptional lifestyles as the norm."},{"kind":"sentence","front":"I occasionally go out to restaurants.","meaning":"","example":""},{"kind":"sentence","front":"You have to add the ingredients in the right order.","meaning":"","example":""},{"kind":"sentence","front":"How could these two issues possibly be connected?","meaning":"","example":""},{"kind":"sentence","front":"I’ve been getting a little lazy lately.","meaning":"","example":""},{"kind":"sentence","front":"Very few students were actually paying attention in class.","meaning":"","example":""},{"kind":"sentence","front":"Students were on their phones.","meaning":"","example":""},{"kind":"sentence","front":"I sometimes make grammatical mistakes.","meaning":"","example":""},{"kind":"sentence","front":"I’m mainly focused on everyday communication.","meaning":"","example":""},{"kind":"sentence","front":"We didn’t go into much depth.","meaning":"","example":""},{"kind":"sentence","front":"We’ve been comparing ourselves with others since we were young.","meaning":"","example":""},{"kind":"paragraph","front":"I cook most of my meals myself, but I've started eating out once or twice a week. I did the math, and it doesn't cost me that much. The biggest issue is that I live in a dorm and only have an electric pot in my room. Without a proper stove, my options are limited. Even making noodles takes planning because I have to add the ingredients in the right order. Sometimes I wonder whether spending so much time cooking is really worth the hassle.","meaning":"","example":""},{"kind":"paragraph","front":"My neighbor's heavy footsteps and chair scrapes come through the thin walls as low-frequency thumps. I open my window to let in background noise that masks them, but in winter a cold draft comes in too.","meaning":"","example":""},{"kind":"paragraph","front":"This morning, I practiced English for about an hour before going to class. I could tell I was making progress, but I still felt mentally exhausted. The lectures were even more frustrating because I couldn't always follow what the lecturer was saying. At the same time, I noticed that the rates on my delivery app had gone up. That made me think about the opportunity cost of staying in class. I know education matters, but I can't help wondering whether my time would sometimes be better spent elsewhere.","meaning":"","example":""},{"kind":"paragraph","front":"My main goal isn't to become a translator or use complicated academic language. I want to have a good command of everyday English so I can communicate naturally with people from different backgrounds. I can usually get my point across, but sometimes I struggle to find the right words. I don't mind making minor grammatical mistakes as long as they don't cause misunderstandings. What matters most to me is being able to go beyond small talk and have more in-depth conversations.","meaning":"","example":""},{"kind":"paragraph","front":"I think social comparison is part of human nature. Even before social media, people compared themselves with neighbors, classmates, and colleagues. Social media acts as an amplifier: now we can see the lifestyles of extremely wealthy people thousands of miles away. That can set unrealistic expectations and fuel envy and dissatisfaction. In my experience growing up in China, competition started early, with comparisons of grades and achievements. The goalposts kept moving, and it sometimes felt like the rat race would never end. I don't think competition is always harmful, but constantly measuring your self-worth against other people can be mentally exhausting.","meaning":"","example":""},{"kind":"phrase","front":"shake out your clothes","meaning":"把衣服抖开、甩一甩","example":"Give your clothes a good shake before hanging them up."},{"kind":"phrase","front":"hang them up to dry","meaning":"挂起来晾干","example":"Shake them out before you hang them up to dry."},{"kind":"phrase","front":"get all wrinkled","meaning":"变得皱巴巴","example":"They’ll get all wrinkled if you leave them in a pile."},{"kind":"phrase","front":"crumpled / wrinkled","meaning":"揉成一团、皱成一团 / 表面起褶皱","example":"The shirt was crumpled in my bag and came out wrinkled."},{"kind":"phrase","front":"walk towards each other","meaning":"相向而行；迎面走来","example":"We were walking towards each other along the pavement."},{"kind":"phrase","front":"approach each other","meaning":"逐渐靠近彼此","example":"Two people were approaching each other from opposite directions."},{"kind":"phrase","front":"walk past each other","meaning":"相向走过、擦肩而过","example":"We walked past each other without saying a word."},{"kind":"phrase","front":"almost bump into each other","meaning":"差点迎面撞上","example":"We almost bumped into each other at the doorway."},{"kind":"phrase","front":"with the help of ...","meaning":"在……帮助下","example":"I’m improving my spoken English with the help of AI."},{"kind":"phrase","front":"thanks to ...","meaning":"多亏、得益于","example":"Thanks to the quiet study room, I can finally concentrate."},{"kind":"phrase","front":"rely on ...","meaning":"依靠、依赖","example":"I rely on a quiet environment to do focused work."},{"kind":"phrase","front":"leverage ...","meaning":"充分利用（常见于商业语境）","example":"Investors sometimes leverage their experience to spot opportunities."},{"kind":"phrase","front":"fall into a routine / be in a routine","meaning":"形成固定作息、进入规律","example":"I’ve fallen into a routine: breakfast, campus, study, repeat."},{"kind":"phrase","front":"my days blur together","meaning":"每天都差不多，日子混在一起","example":"I do similar things every day, so my days blur together."},{"kind":"phrase","front":"a repetitive routine","meaning":"重复性的日常","example":"My routine is repetitive, but I don’t mind it."},{"kind":"phrase","front":"not a morning person / an early bird","meaning":"不习惯早起的人 / 早起型的人","example":"I’m not a morning person, even though I get up early."},{"kind":"phrase","front":"a night owl","meaning":"夜猫子、晚间精力旺盛的人","example":"I’m definitely a night owl; I think more clearly at night."},{"kind":"phrase","front":"feel mentally alert","meaning":"头脑清醒、精神敏锐","example":"I feel much more mentally alert after sunset."},{"kind":"phrase","front":"my brain kicks into gear","meaning":"大脑开始进入状态","example":"It takes a while for my brain to kick into gear."},{"kind":"phrase","front":"get a second wind","meaning":"突然恢复精力","example":"I often get a second wind late at night."},{"kind":"phrase","front":"feel groggy","meaning":"刚睡醒昏沉","example":"I feel groggy for quite a while after waking up."},{"kind":"phrase","front":"take time to get going","meaning":"需要时间进入状态","example":"It takes me longer than average to get going in the morning."},{"kind":"phrase","front":"warm up mentally","meaning":"让头脑慢慢进入状态","example":"I need time to warm up mentally before doing difficult work."},{"kind":"phrase","front":"carve out some quiet time","meaning":"挤出、专门留出安静时间","example":"I’ve carved out a few hours to study without distractions."},{"kind":"phrase","front":"at my own pace","meaning":"按照自己的节奏","example":"I prefer studying at my own pace."},{"kind":"phrase","front":"stay focused / concentrate on","meaning":"保持专注 / 专心于","example":"It’s much easier to stay focused when nobody interrupts me."},{"kind":"phrase","front":"a small price to pay for ...","meaning":"为了……值得付出的一点代价","example":"A ten-minute walk is a small price to pay for a quiet day."},{"kind":"phrase","front":"my mood goes downhill","meaning":"心情变差、一路下滑","example":"When the thumping starts, my mood goes downhill."},{"kind":"phrase","front":"heavy thuds / thumping","meaning":"沉重的咚咚声、撞击声","example":"Heavy thuds from next door make it hard to concentrate."},{"kind":"phrase","front":"crack the window open","meaning":"把窗户开一条缝","example":"I cracked the window open to let some air in."},{"kind":"phrase","front":"leave the window slightly open","meaning":"窗户留一条小缝","example":"I leave the window slightly open even when it’s cold."},{"kind":"phrase","front":"let some fresh air in","meaning":"让新鲜空气进来","example":"A little fresh air helps me stay awake."},{"kind":"phrase","front":"cut right through my jacket","meaning":"冷风穿透衣服、吹得透心凉","example":"The wind at eight in the morning cut right through my jacket."},{"kind":"phrase","front":"wear two mid-layers","meaning":"穿两层中间保暖层","example":"I had to wear two mid-layers to stay warm."},{"kind":"phrase","front":"soak up some sunshine","meaning":"晒晒太阳、享受阳光","example":"I’m just sitting by the window, soaking up some sunshine."},{"kind":"phrase","front":"the radiator / the heating is on","meaning":"暖气片 / 暖气开着","example":"The heating is on, so the room gets warm quickly."},{"kind":"phrase","front":"turn the heating up / down","meaning":"把暖气调高 / 调低","example":"They turn the heating up when temperatures drop."},{"kind":"phrase","front":"the room gets stuffy","meaning":"房间变得闷、不通风","example":"If the windows stay shut, the room gets stuffy."},{"kind":"phrase","front":"feel drowsy","meaning":"昏昏欲睡","example":"An overheated room makes me feel drowsy."},{"kind":"phrase","front":"perk me up","meaning":"使我精神一振","example":"A little cool air perks me up."},{"kind":"phrase","front":"stay alert / clear-headed","meaning":"保持清醒 / 头脑清楚","example":"Fresh air helps me stay alert and clear-headed."},{"kind":"phrase","front":"adjust the heating depending on the weather","meaning":"根据天气调节暖气","example":"The building adjusts the heating depending on the weather."},{"kind":"phrase","front":"the Wi-Fi keeps dropping out","meaning":"无线网络总是断连","example":"The university Wi-Fi keeps dropping out in the middle of calls."},{"kind":"phrase","front":"the connection cuts in and out","meaning":"网络连接时断时续","example":"The connection keeps cutting in and out."},{"kind":"phrase","front":"the Wi-Fi is unreliable / laggy","meaning":"无线网络不稳定 / 延迟很高","example":"It’s frustrating that the campus Wi-Fi is so unreliable."},{"kind":"phrase","front":"a contradiction between A and B","meaning":"A 和 B 之间存在矛盾","example":"There can be a contradiction between efficiency and fairness."},{"kind":"phrase","front":"a trade-off between A and B","meaning":"A 和 B 之间需要权衡","example":"There’s often a trade-off between efficiency and fairness."},{"kind":"phrase","front":"sound contradictory / paradoxical","meaning":"听起来矛盾 / 悖论式的","example":"It sounds paradoxical, but a small hassle can save time later."},{"kind":"phrase","front":"tension between two goals","meaning":"两个目标之间的张力与冲突","example":"There’s tension between maximizing efficiency and ensuring fairness."},{"kind":"phrase","front":"push in different directions","meaning":"朝不同方向拉扯、彼此冲突","example":"The two goals sometimes push in different directions."},{"kind":"phrase","front":"sacrifice some fairness for efficiency","meaning":"为提高效率牺牲一部分公平","example":"Improving efficiency can sometimes mean sacrificing some fairness."},{"kind":"phrase","front":"a turning point / a contrast","meaning":"转折点 / 对照转折关系","example":"Use “but” when the second clause introduces a genuine contrast."},{"kind":"phrase","front":"I’m not making it up","meaning":"我不是凭空编的","example":"I’m not making it up; economists really do debate this trade-off."},{"kind":"phrase","front":"the market has plunged","meaning":"市场暴跌","example":"The Chinese stock market has plunged recently."},{"kind":"phrase","front":"take a nosedive","meaning":"突然大跌、断崖式下跌","example":"The market took a nosedive over a short period."},{"kind":"phrase","front":"pull back / a pullback","meaning":"回撤、相对温和的调整","example":"A pullback sounds less dramatic than a plunge."},{"kind":"phrase","front":"weather the downturn","meaning":"挺过市场下行期","example":"My portfolio has weathered the downturn fairly well."},{"kind":"phrase","front":"take a hit / hold up well","meaning":"受到冲击 / 顶住压力","example":"The market took a hit, but my portfolio held up well."},{"kind":"phrase","front":"outperform the market / an index","meaning":"跑赢市场 / 指数","example":"My portfolio has outperformed the Chinese market over that period."},{"kind":"phrase","front":"beat the market","meaning":"跑赢大盘（更口语）","example":"I’ve beaten the market so far this year."},{"kind":"phrase","front":"since I started investing","meaning":"自我开始投资以来","example":"I’ve learned a lot since I started investing."},{"kind":"phrase","front":"over that period","meaning":"在那段期间内","example":"My holdings performed better over that period."},{"kind":"phrase","front":"an investment portfolio / holdings","meaning":"投资组合 / 持仓","example":"A large part of my portfolio consists of U.S. holdings."},{"kind":"phrase","front":"a niche interest","meaning":"小众兴趣","example":"Stock investing is still a niche interest in my social circle."},{"kind":"phrase","front":"keep my investment decisions to myself","meaning":"投资决策自己做、不轻易与人讨论","example":"I usually keep my investment decisions to myself."},{"kind":"phrase","front":"strike up a conversation about stocks","meaning":"主动聊起股票","example":"I rarely strike up a conversation about stocks with classmates."},{"kind":"phrase","front":"see things the same way","meaning":"看法一致","example":"I don’t need people to see things the same way as I do."},{"kind":"phrase","front":"opposing views / a counterargument","meaning":"相反观点 / 反驳论据","example":"I’m happy to read opposing views if they’re well reasoned."},{"kind":"phrase","front":"back up a claim with evidence","meaning":"用证据支持观点","example":"People should back up their claims with reasoning, not emotion."},{"kind":"phrase","front":"insider information / inside information","meaning":"内幕信息","example":"Most casual conversations don’t provide genuine inside information."},{"kind":"phrase","front":"already priced in","meaning":"已经反映在价格里","example":"That information might already be priced in."},{"kind":"phrase","front":"introverted, not necessarily shy","meaning":"内向，但不一定害羞","example":"I’m introverted, but that doesn’t mean I’m shy."},{"kind":"phrase","front":"feel self-conscious","meaning":"在意他人眼光而局促不安","example":"I sometimes feel self-conscious around strangers."},{"kind":"phrase","front":"feel neutral about ...","meaning":"对……既不紧张也不兴奋","example":"Sometimes I feel neutral about talking to classmates."},{"kind":"phrase","front":"socialize / be sociable","meaning":"参加社交、与人交往 / 善于交际","example":"I can socialize when I need to; I just don’t always want to."},{"kind":"phrase","front":"build a social network / network with people","meaning":"建立人际关系 / 社交拓展人脉","example":"Being introverted doesn’t mean I can’t network with people."},{"kind":"phrase","front":"when it matters","meaning":"真正需要的时候","example":"I can speak up when it matters."},{"kind":"phrase","front":"social etiquette","meaning":"社交礼仪","example":"I usually follow social etiquette, even when I feel uncomfortable."},{"kind":"phrase","front":"feel obligated to stay","meaning":"觉得有义务留下","example":"I sometimes feel obligated to stay until the party ends."},{"kind":"phrase","front":"leave early / leave abruptly","meaning":"提前离开 / 突然离场","example":"I’d feel awkward leaving early while everyone else stayed."},{"kind":"phrase","front":"slam the door","meaning":"砰地关门；也可比喻粗暴断绝关系","example":"I don’t want to slam the door and leave abruptly."},{"kind":"phrase","front":"I might already have plans","meaning":"我可能已经有别的安排","example":"I might already have plans, so I can’t promise I’ll come."},{"kind":"phrase","front":"show up / make it to the event","meaning":"到场 / 赶得上活动","example":"I’m not sure I can make it to the meeting."},{"kind":"phrase","front":"feel drained / drain my energy","meaning":"感到精疲力尽 / 耗尽我的精力","example":"Long social gatherings can drain my energy."},{"kind":"phrase","front":"enjoy my own company","meaning":"享受独处","example":"I enjoy my own company, reading or playing games."},{"kind":"phrase","front":"be torn between A and B","meaning":"在 A 和 B 之间纠结","example":"I’m torn between staying home and going to a gathering."},{"kind":"phrase","front":"I’m torn between A and B","meaning":"在两个选择之间纠结","example":"I’m torn between cooking at home and getting KFC."},{"kind":"phrase","front":"be on the fence about ...","meaning":"对……犹豫未决","example":"I’m still on the fence about ordering takeout."},{"kind":"phrase","front":"a promotion / a special offer","meaning":"促销活动 / 优惠","example":"KFC has a special offer on hot wings today."},{"kind":"phrase","front":"a pretty good deal / an attractive price","meaning":"价格相当划算","example":"Fifteen hot wings for nine euros sounds like a pretty good deal."},{"kind":"phrase","front":"notice a promotion","meaning":"注意到促销","example":"I never used to pay attention to these promotions."},{"kind":"phrase","front":"go bad / start turning yellow","meaning":"变质 / 开始发黄","example":"If I leave the broccoli any longer, it might start turning yellow."},{"kind":"phrase","front":"dry out","meaning":"失去水分，逐渐干掉","example":"The vegetables will dry out if I leave them too long."},{"kind":"phrase","front":"I’m not entirely sure what was in it","meaning":"我不太确定里面是什么","example":"I’m not entirely sure what was in the second burger."},{"kind":"phrase","front":"made with chicken","meaning":"用鸡肉制作","example":"Both burgers were made with chicken."},{"kind":"phrase","front":"come with a sweet sauce","meaning":"配有甜酱","example":"One of the burgers came with a sweet sauce."},{"kind":"phrase","front":"not really to my taste","meaning":"不太合我的口味","example":"That sauce wasn’t really to my taste."},{"kind":"phrase","front":"too sweet for my liking","meaning":"对我而言太甜了","example":"The sauce was a bit too sweet for my liking."},{"kind":"phrase","front":"savory / savoury","meaning":"咸鲜口的（美/英拼写）","example":"I like both sweet and savory food, just not that combination."},{"kind":"phrase","front":"the combination doesn’t work for me","meaning":"这个搭配我接受不了","example":"Sweet sauce and chicken just don’t work for me."},{"kind":"phrase","front":"a large order of fries","meaning":"一大份薯条","example":"I had two chicken burgers and a large order of fries."},{"kind":"phrase","front":"plain broccoli","meaning":"不加调味的西兰花","example":"I usually eat plain broccoli to keep things simple."},{"kind":"phrase","front":"minced garlic / dice the garlic","meaning":"蒜末 / 把蒜切丁","example":"People often add minced garlic to vegetables."},{"kind":"phrase","front":"an electric pot / turn on the stove","meaning":"电煮锅 / 打开炉灶","example":"I use an electric pot rather than a stove."},{"kind":"phrase","front":"bring the water to a boil","meaning":"把水烧开","example":"Bring the water to a boil before adding the broccoli."},{"kind":"phrase","front":"cook through / cook quickly","meaning":"熟透 / 熟得快","example":"Different ingredients take different amounts of time to cook through."},{"kind":"phrase","front":"the easiest / most effortless part","meaning":"最容易 / 最不费力的部分","example":"Boiling vegetables is the most effortless part of cooking."},{"kind":"phrase","front":"the clean-up is easy","meaning":"收拾清洗很简单","example":"With one pot, the clean-up is easy."},{"kind":"phrase","front":"purchasing power","meaning":"购买力","example":"Groceries cost less back home, so I’d have more purchasing power."},{"kind":"phrase","front":"my money goes further","meaning":"同样的钱更经花","example":"My money would go a lot further in China."},{"kind":"phrase","front":"not much of a shopper","meaning":"不太爱购物的人","example":"I’m not much of a shopper, so I don’t miss shopping malls."},{"kind":"phrase","front":"not particularly materialistic","meaning":"物质欲望不强","example":"I’m not particularly materialistic, and I enjoy simple hobbies."},{"kind":"phrase","front":"my quality of life has taken a hit","meaning":"生活质量受到了影响","example":"My day-to-day quality of life has taken a hit in the dorm."},{"kind":"phrase","front":"day-to-day comfort / convenience","meaning":"日常舒适度 / 便利性","example":"I’ve given up some day-to-day comfort by moving abroad."},{"kind":"phrase","front":"a trade-off / give up A in exchange for B","meaning":"取舍 / 放弃 A 换取 B","example":"I’ve traded some convenience for more opportunities abroad."},{"kind":"phrase","front":"broaden my horizons","meaning":"开阔眼界","example":"Living in Europe has helped me broaden my horizons."},{"kind":"phrase","front":"keep my options open","meaning":"给未来保留选择空间","example":"I want to keep my options open for the future."},{"kind":"phrase","front":"a concrete benefit","meaning":"实实在在的好处","example":"Traveling around Europe is one concrete benefit of living here."},{"kind":"phrase","front":"a round-trip ticket / airfare alone","meaning":"往返机票 / 光是机票","example":"The round-trip airfare alone could cost five hundred euros."},{"kind":"phrase","front":"get to travel around Europe","meaning":"有机会周游欧洲","example":"I’ve been able to travel around Europe much more affordably."},{"kind":"phrase","front":"I’ve been to around ten European countries","meaning":"我已经去过大约十个欧洲国家","example":"I’ve been to around ten European countries since moving here."},{"kind":"phrase","front":"worth the sacrifice","meaning":"值得为之牺牲","example":"Whether the experience is worth the sacrifice is a separate question."},{"kind":"phrase","front":"historical and cultural attractions / sites","meaning":"历史与人文景点","example":"I’m not especially interested in historical and cultural sites."},{"kind":"phrase","front":"ancient ruins / historical remains","meaning":"古代遗迹 / 历史遗存","example":"Many museums display objects and remains from earlier periods."},{"kind":"phrase","front":"the Middle Ages / medieval history","meaning":"中世纪 / 中世纪历史","example":"I don’t always feel engaged by medieval history."},{"kind":"phrase","front":"be famous for its history","meaning":"以其悠久历史著称","example":"Some cities are famous for their history."},{"kind":"phrase","front":"have historical significance","meaning":"具有历史意义","example":"I know those places have historical significance."},{"kind":"phrase","front":"a must-see attraction","meaning":"必看、必去景点","example":"I sometimes feel pressure to visit every must-see attraction."},{"kind":"phrase","front":"feel obligated to do something","meaning":"觉得有义务做某事","example":"I feel obligated to visit famous historical sites."},{"kind":"phrase","front":"a sense of duty / responsibility","meaning":"责任感、使命感","example":"It feels like a responsibility rather than genuine excitement."},{"kind":"phrase","front":"go out of obligation, not interest","meaning":"出于义务而非兴趣去做","example":"Sometimes I visit museums out of obligation, not interest."},{"kind":"phrase","front":"feel uncomfortable skipping it","meaning":"跳过会觉得不踏实","example":"I’d feel uncomfortable skipping an important historical site."},{"kind":"phrase","front":"natural scenery / scenic landscapes","meaning":"自然风景 / 风景优美的景观","example":"Natural scenery appeals to me far more than old buildings."},{"kind":"phrase","front":"snow-capped mountains / blue seas","meaning":"雪山 / 蔚蓝的海","example":"I get excited by snow-capped mountains and blue seas."},{"kind":"phrase","front":"hiking trails / coastal landscapes","meaning":"徒步路线 / 海岸景观","example":"I love hiking trails and coastal landscapes."},{"kind":"phrase","front":"lift my mood / turn my mood around","meaning":"改善心情、使心情好转","example":"A beautiful landscape can lift my mood immediately."},{"kind":"phrase","front":"come alive","meaning":"一下子精神起来、变得活跃","example":"I seem to come alive when I reach a scenic viewpoint."},{"kind":"phrase","front":"pay attention to my own reaction","meaning":"留意自己的真实反应","example":"My reaction tells me more about my preferences than famous rankings do."},{"kind":"phrase","front":"rather than a “want,” it feels like a “should”","meaning":"不是想去，而是觉得应该去","example":"Visiting some museums feels more like a “should” than a “want.”"},{"kind":"sentence","front":"Give your clothes a good shake, or they’ll get all wrinkled.","meaning":"","example":""},{"kind":"sentence","front":"Two people are walking towards each other.","meaning":"","example":""},{"kind":"sentence","front":"I eat basically the same breakfast and go to the same building every day.","meaning":"","example":""},{"kind":"sentence","front":"I’m not a morning person.","meaning":"","example":""},{"kind":"sentence","front":"I need somewhere quiet where nobody will interrupt me.","meaning":"","example":""},{"kind":"sentence","front":"It’s a bit of a hassle.","meaning":"","example":""},{"kind":"sentence","front":"A little hassle now makes the rest of the day easier.","meaning":"","example":""},{"kind":"sentence","front":"This draft doesn’t make me feel cold.","meaning":"","example":""},{"kind":"sentence","front":"They turn the heating on in October.","meaning":"","example":""},{"kind":"sentence","front":"There’s often a trade-off between efficiency and fairness.","meaning":"","example":""},{"kind":"sentence","front":"How can I use “but” to show a contrast?","meaning":"","example":""},{"kind":"sentence","front":"My portfolio has outperformed the index.","meaning":"","example":""},{"kind":"sentence","front":"My portfolio outperformed the index over that period.","meaning":"","example":""},{"kind":"sentence","front":"Stock investing is still a niche interest in my social circle.","meaning":"","example":""},{"kind":"sentence","front":"The market may not care about that information.","meaning":"","example":""},{"kind":"sentence","front":"It may already be priced in.","meaning":"","example":""},{"kind":"sentence","front":"Sometimes people think I’m shy.","meaning":"","example":""},{"kind":"sentence","front":"I can socialize when I need to.","meaning":"","example":""},{"kind":"sentence","front":"I’m more into spending time alone.","meaning":"","example":""},{"kind":"sentence","front":"I can’t promise I’ll be there.","meaning":"","example":""},{"kind":"sentence","front":"I’m not sure I can make it.","meaning":"","example":""},{"kind":"sentence","front":"I’m torn between two options.","meaning":"","example":""},{"kind":"sentence","front":"I’m torn between cooking at home and getting KFC.","meaning":"","example":""},{"kind":"sentence","front":"KFC is running a promotion today.","meaning":"","example":""},{"kind":"sentence","front":"KFC has a special offer.","meaning":"","example":""},{"kind":"sentence","front":"It only costs nine euros.","meaning":"","example":""},{"kind":"sentence","front":"I never used to notice these kinds of promotions.","meaning":"","example":""},{"kind":"sentence","front":"Some broccoli in my dorm room.","meaning":"","example":""},{"kind":"sentence","front":"I’m not even sure what was in them.","meaning":"","example":""},{"kind":"sentence","front":"A burger made with chicken.","meaning":"","example":""},{"kind":"sentence","front":"The sweet sauce isn’t really to my taste.","meaning":"","example":""},{"kind":"sentence","front":"Wait for the water to boil.","meaning":"","example":""},{"kind":"sentence","front":"I have greater purchasing power.","meaning":"","example":""},{"kind":"sentence","front":"My quality of life has gone down.","meaning":"","example":""},{"kind":"sentence","front":"I’ve realized I’m not that interested in historical sites.","meaning":"","example":""},{"kind":"sentence","front":"I’m interested in historical sites.","meaning":"","example":""},{"kind":"sentence","front":"Natural scenery appeals to me much more.","meaning":"","example":""},{"kind":"sentence","front":"I feel obligated to visit.","meaning":"","example":""},{"kind":"sentence","front":"It feels like a responsibility.","meaning":"","example":""},{"kind":"paragraph","front":"My days are pretty repetitive. I wake up around the same time, eat roughly the same breakfast, and head to the same academic building. I'm not really a morning person, so getting out of bed can be a struggle. But the dorm is noisy, and I need somewhere I can focus. Walking over to the building is a small price to pay for a whole day of peace. Once I'm there, I can study at my own pace without anyone interrupting me.","meaning":"","example":""},{"kind":"paragraph","front":"I'm definitely a night owl. My brain seems to kick into gear later in the evening, and I can get a surprising amount done. In the morning, though, I feel groggy and need a while to get going. When the heating is on, the study room can get stuffy and make me drowsy. I usually crack the window open to let some fresh air in. Even if there's a slight draft, it perks me up and helps me stay alert.","meaning":"","example":""},{"kind":"paragraph","front":"The Chinese stock market has plunged recently, but my portfolio has held up relatively well and outperformed the index over that period. I tend to keep my investment decisions to myself. Investing is still a niche interest in my social circle, and I don't find it useful to debate stocks with people who only repeat their feelings. I'm happy to read opposing views, but I want to see clear reasoning and evidence. Information that's already priced in doesn't really give me an edge.","meaning":"","example":""},{"kind":"paragraph","front":"People sometimes assume I'm shy because I keep to myself. I can feel self-conscious in certain situations, but being introverted doesn't mean I can't socialize. It just means I enjoy my own company and need time to myself. When a conversation matters, I can take part. At parties, I usually follow social etiquette even if I'm not enjoying myself. That's partly why I prefer to decline invitations politely rather than leave early and feel awkward.","meaning":"","example":""},{"kind":"paragraph","front":"I was torn between cooking at home and getting KFC because there was a pretty good promotion on hot wings. The price was tempting, but I'd already had KFC the day before. I also had some broccoli in my room that was starting to turn yellow. So I was leaning towards cooking at home. I don't particularly enjoy plain broccoli, but boiling it is effortless: I just bring the water to a boil, add the broccoli, and wait a few minutes. The clean-up is easy too.","meaning":"","example":""},{"kind":"paragraph","front":"I'm not much of a shopper, so shopping malls and cinemas don't make much difference to me. Food and living conditions are another story. Back in China, my money would go further, and I'd have access to food that suits my taste. My quality of life has taken a hit in some day-to-day ways since I moved into a dorm. But living in Lithuania has also given me the opportunity to travel around Europe much more easily. I've visited around ten European countries, and the airfare alone would have made those trips more expensive from China. For now, I see it as a trade-off: less comfort in some areas, but more opportunities to broaden my horizons.","meaning":"","example":""},{"kind":"paragraph","front":"I've realized that I'm not as interested in historical and cultural sites as I once thought. I understand why ancient ruins, museums and medieval buildings matter to human civilization, and I sometimes feel obligated to visit them when I'm in a historic city. But that sense of duty isn't the same as genuine excitement. Natural scenery appeals to me much more. Snow-capped mountains, blue seas and hiking trails can lift my mood almost immediately. It's strange: I may feel tired after visiting several museums, but when I reach a beautiful natural landscape, I suddenly feel excited again. That reaction tells me a lot about what I really enjoy.","meaning":"","example":""},{"kind":"phrase","front":"It takes me + time + to + verb","meaning":"做某事需要我……时间","example":"It takes me a while to get going in the morning."},{"kind":"phrase","front":"A is a small price to pay for B","meaning":"为了 B，A 是值得付出的小代价","example":"A ten-minute walk is a small price to pay for some peace."},{"kind":"phrase","front":"The idea of A is ... / A can be ...","meaning":"用抽象名词化方式表达评价","example":"The idea of leaving a famous site unseen makes me uncomfortable."},{"kind":"phrase","front":"I’m not really into + noun / -ing","meaning":"我不太喜欢……","example":"I’m not really into visiting museums."},{"kind":"phrase","front":"It’s not that ..., it’s just that ...","meaning":"不是说……而是……","example":"It’s not that I’m shy; it’s just that I enjoy being alone."},{"kind":"phrase","front":"Even though + clause, main clause","meaning":"即使……仍然……","example":"Even though the market fell, my portfolio held up fairly well."},{"kind":"phrase","front":"A appeals to me much more than B","meaning":"A 比 B 更吸引我","example":"Natural scenery appeals to me much more than historical sites."},{"kind":"phrase","front":"I feel obligated to + verb","meaning":"感觉理应去做……","example":"I feel obligated to visit important historical sites."},{"kind":"phrase","front":"I can’t help but + verb","meaning":"忍不住……","example":"I can’t help but wonder whether the experience is worth it."},{"kind":"phrase","front":"I’ve realized that ...","meaning":"我逐渐意识到……","example":"I’ve realized that I prefer nature to museums."},{"kind":"phrase","front":"A has taken a hit, but ...","meaning":"A 受到冲击，但……","example":"My daily comfort has taken a hit, but I’ve gained other opportunities."},{"kind":"phrase","front":"Since + past point, present perfect","meaning":"自某时间点以来……","example":"Since I moved here, I’ve visited several European countries."},{"kind":"phrase","front":"A has outperformed B over that period","meaning":"A 在那段期间跑赢 B","example":"My portfolio has outperformed the index over that period."},{"kind":"phrase","front":"If I’d ..., I would have ...","meaning":"与过去事实相反的假设","example":"If I’d stayed in China, traveling around Europe would have cost more."},{"kind":"phrase","front":"running late","meaning":"要迟到了","example":"I'm running late for class."},{"kind":"phrase","front":"make it / barely make it","meaning":"赶到／勉强赶上","example":"We barely made it to the train on time."},{"kind":"phrase","front":"go our separate ways","meaning":"各自离开","example":"After the meeting, we went our separate ways."},{"kind":"phrase","front":"have the whole place to myself","meaning":"独占整个空间、几乎没人","example":"I had the whole study room to myself."},{"kind":"phrase","front":"a sense of freedom","meaning":"自由感","example":"Walking alone gives me a sense of freedom."},{"kind":"phrase","front":"upbeat","meaning":"轻快、积极的","example":"She stayed upbeat despite the bad weather."},{"kind":"phrase","front":"come to mind","meaning":"浮现脑海","example":"Nothing comes to mind right now."},{"kind":"phrase","front":"keep someone up","meaning":"让某人睡不着","example":"The noise kept me up all night."},{"kind":"phrase","front":"soaked / wet / damp / dry","meaning":"湿透／湿／潮湿／干燥","example":"My jacket was soaked after the hike, but my socks stayed dry."},{"kind":"phrase","front":"leak / spill / drip / drain / splatter","meaning":"漏／洒／滴／排走／飞溅","example":"Water started dripping from the pipe."},{"kind":"phrase","front":"drag / bulky / get stuck / squeeze through","meaning":"拖／笨重／卡住／挤过去","example":"The bulky bag got stuck in the doorway."},{"kind":"phrase","front":"stale / fresh","meaning":"不新鲜／新鲜","example":"The bread went stale overnight."},{"kind":"phrase","front":"firm / mushy","meaning":"紧实／软烂","example":"Cook the broccoli until it's tender but not mushy."},{"kind":"phrase","front":"unripe → ripe → overripe → rotten","meaning":"未熟→成熟→熟过头→腐烂","example":"The fruit went from unripe to overripe before I could eat it."}];
